import{_ as t,o,c as d,a2 as a}from"./chunks/framework.CdvW4CUT.js";const u=JSON.parse('{"title":"Platforms and what has been verified","description":"","frontmatter":{},"headers":[],"relativePath":"platforms.md","filePath":"platforms.md"}'),r={name:"platforms.md"};function n(s,e,i,c,l,h){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="platforms-and-what-has-been-verified" tabindex="-1">Platforms and what has been verified <a class="header-anchor" href="#platforms-and-what-has-been-verified" aria-label="Permalink to &quot;Platforms and what has been verified&quot;">​</a></h1><p>&quot;Works&quot; below means it has run for real, not only compiled or passed unit tests.</p><h2 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Status</th></tr></thead><tbody><tr><td><code>apt</code>, <code>dnf</code>, <code>pacman</code>: install, uninstall, rollback</td><td>Verified: Ubuntu 24.04 (arm64), Fedora 41 (arm64), Arch (amd64), in containers</td></tr><tr><td><code>shell</code> (<code>typescript</code>), dependency chains</td><td>Verified on the same three</td></tr><tr><td><code>github_release</code> (<code>ripgrep</code>), checksum check</td><td>Verified on the same three</td></tr><tr><td><code>outdated</code>, <code>upgrade</code></td><td>Verified with a real older <code>git</code> on Ubuntu (<code>apt</code>) and Fedora (<code>dnf</code>). <code>pacman</code> upgrades are unit-tested only: Arch keeps no old versions to test with</td></tr><tr><td><code>lock</code>, install from <code>ripeat.lock</code></td><td>Verified on the same three</td></tr><tr><td><code>ripeat mcp</code> over real standard input and output, including <code>--allow-run</code> (the confirmation dialog, a real <code>github_release</code> install and its rollback, the refusal of a step that needs administrator rights)</td><td>Tried by hand in an Ubuntu 24.04 container (the assistant test notes); no CI job. The unit tests cover the same flow with an in-memory client</td></tr><tr><td>Recipe packs (<code>ripeat tap</code>)</td><td>Unit-tested against a fake GitHub, and tried by hand on macOS against a <strong>real private GitHub repository</strong> with a token: add (two recipes, one shell recipe refused, the commit pinned), <code>plan</code> and <code>assess</code> (the risk reason names the pack), a change pushed to the repository, then <code>update</code> (the new commit, an added recipe, a line-by-line diff of a changed one, the pin moving only after the answer). Not tried on Windows or Linux</td></tr><tr><td><code>policy</code> (users, groups, admin)</td><td>Verified on the same three</td></tr><tr><td><code>validate</code>, <code>schema</code></td><td>Verified on the same three</td></tr><tr><td><code>find</code> and <code>add</code> (<code>apt</code>, <code>dnf</code>, <code>pacman</code> lookups; GitHub release drafts that download and inspect the real file)</td><td>Verified on the same three</td></tr><tr><td>Administrator policy (<code>/etc/ripeat/policy.yaml</code>): blocking, fallbacks, never blocking removal, refusing a file that is not root-owned</td><td>Verified on the same three containers. The &quot;not owned by root&quot; refusal is only exercised by the Ubuntu VM and macOS CI jobs, and counts as verified only while those pass</td></tr><tr><td>Restart detection, pause and <code>resume</code> (via <code>/var/run/reboot-required</code>)</td><td>Verified on the same three; <code>needs-restarting -r</code> not exercised</td></tr><tr><td>ripeat running as a normal user through <code>sudo</code></td><td>Covered by the Ubuntu VM CI job (<code>scripts/linux-vm-test.sh</code>, passwordless <code>sudo</code>); the container tests run as root, where <code>sudo</code> is never used</td></tr><tr><td>The interactive <code>sudo</code> password prompt</td><td>Not verified: no CI can type a password</td></tr><tr><td><code>deb_url</code> (the <code>vscode</code> recipe), <code>snap</code> (<code>hello</code>), <code>flatpak</code> (GNOME Calculator)</td><td>Covered by the same VM job. Treat as verified only while that job passes; a missing <code>snap</code> is reported as skipped. <code>deb_url</code> for <code>chrome</code> is not exercised (Chrome is preinstalled on the runner)</td></tr></tbody></table><h2 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h2><p>The administrator policy file (<code>%ProgramData%\\ripeat\\policy.yaml</code>) is read and enforced the same way, but ripeat does not check its ACL, and nothing tests it on Windows.</p><p>Everything compiles and the logic is unit-tested. A CI job also runs <code>scripts/windows-test.ps1</code> on a GitHub Windows runner (the test notes): real <code>choco</code>, <code>scoop</code> and <code>winget</code> installs, the GitHub download with a lockfile, the PowerShell user and group commands, and restart detection and <code>resume</code>.</p><p>Checked by hand on a real Windows 11 ARM64 machine (a VMware virtual machine; steps in the Windows test notes), 2 November 2026:</p><table tabindex="0"><thead><tr><th>What</th><th>Result</th></tr></thead><tbody><tr><td><code>scoop install ripeat</code> from the bucket, <code>plan</code>, <code>assess</code>, <code>find</code></td><td>worked</td></tr><tr><td><code>install</code> and <code>rollback</code> of <code>ripgrep</code> (GitHub release, no administrator rights)</td><td>worked</td></tr><tr><td><code>install</code> and <code>rollback</code> of <code>node</code> through <code>winget</code>, from an administrator window</td><td>worked; the plan marked it <code>admin</code>, MEDIUM risk</td></tr><tr><td><code>policy --apply</code> and <code>rollback</code> (group, disabled user, membership)</td><td>worked; rollback removed all three</td></tr><tr><td>Administrator policy at <code>%ProgramData%\\ripeat\\policy.yaml</code>: a file missing <code>version</code> is refused, a denied method falls back to the next one, all methods denied blocks the tool, no file means no limits</td><td>worked</td></tr><tr><td><code>ripeat mcp</code> answers an MCP <code>initialize</code> request</td><td>worked</td></tr><tr><td>Confirmation question in 0.5.0</td><td><strong>failed</strong>: the console was not recognised as a terminal, so <code>install</code> refused without <code>--yes</code>. Fixed after 0.5.0; the fix was checked by hand on the same machine</td></tr><tr><td><code>ripeat version --check</code> (0.6.0 on Scoop)</td><td>worked: &quot;You have the latest release&quot;</td></tr><tr><td><code>ripeat recipes check</code></td><td>worked: the <code>winget</code> packages and the ripgrep GitHub release were found; <code>choco</code> (not installed) and <code>scoop</code> (no lookup yet) were reported as not checked, <code>typescript</code> (<code>shell</code>) was not checked</td></tr><tr><td><code>ripeat profile export</code> and <code>import</code></td><td>worked: file round trip, a tool with no recipe marked, a plain <code>http://</code> address refused</td></tr><tr><td>Restart and <code>resume</code> on a real pending restart</td><td>not done</td></tr><tr><td><code>ripeat mcp</code> with Claude Code (plan, assess, save a profile) and with Codex (plan)</td><td>worked; see the assistant test notes. Claude Desktop: one conversation (plan, find; no install); it did not use the draft tool because of out-of-date guidance, now fixed</td></tr><tr><td><code>ripeat mcp --allow-run</code></td><td>not run on Windows</td></tr></tbody></table><p>Treat a Windows feature as verified only while that job passes on the current code. The job reports a method as skipped when its tool is missing on the runner, and it runs on a clean server image, not on a real person&#39;s machine, so user-account quirks, antivirus and corporate policy are not covered.</p><p><strong><code>product</code> (the &quot;Add or remove programs&quot; check for installers)</strong> is unit-tested (the name matching, the &quot;is it there&quot; logic, validation) and builds for Windows, but the registry read and reading the product name from an <code>.msi</code> have <strong>not been run on a real Windows machine yet</strong>.</p><p><strong><code>installer</code> for <code>.pkg</code></strong> is unit-tested (payload parsing, the allowed-folder and denied-path rules, which paths are owned, signature and receipt parsing, refusing a damaged record), but not run against a real package: no CI job builds one with <code>pkgbuild</code> yet (<a href="./installers">Vendor installers</a>). Never try it on your own Mac.</p><p><strong><code>installer</code> for <code>.exe</code></strong> is unit-tested (registry diff, Windows command-line parsing, uninstall command choice, argument rules, the same-signer rule, refusals) with stand-in installers and a fake registry list; the real registry and a real vendor <code>.exe</code> have <strong>not</strong> been run (<a href="./installers">Vendor installers</a>).</p><p><strong><code>installer</code> for <code>.msi</code></strong> (<a href="./installers">Vendor installers</a>) was run by hand on a real Windows 11 ARM64 machine with Node.js&#39;s official signed MSI (checksum checked, signer read as OpenJS Foundation, <code>msiexec</code> install, <code>msiexec /x</code> undo, saved file deleted). No CI job installs an MSI.</p><p><strong>Not yet verified:</strong> the lookups added for <code>snap</code>, <code>flatpak</code>, <code>scoop</code> and the Microsoft Store source of <code>winget</code> (<a href="./find-and-add">Install by name</a>). They are unit-tested against sample output of each tool, and the Ubuntu VM job (<code>snap</code>, <code>flatpak</code>) and the Windows job (<code>scoop</code>; the Store is reported, not required) now exercise them for real. Treat each as verified only while those jobs pass, and the Store lookup only after it has been seen to work on a real Windows machine.</p><p>Install by name on Windows: the <code>choco</code> lookup, draft, install and rollback ran for real on the Windows CI runner. The <code>winget</code> lookup is exercised by the same job and counts as verified only while that job passes; its table parsing is the part to watch.</p><h2 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Status</th></tr></thead><tbody><tr><td><code>brew</code> (formulas) and <code>brew_cask</code> (apps): install, uninstall, rollback, <code>outdated</code></td><td>Exercised by <code>scripts/macos-test.sh</code> on a GitHub macOS runner (Apple silicon); treat as verified only while that CI job passes. <code>brew upgrade</code> is unit-tested only (parsing)</td></tr><tr><td><code>github_release</code> (<code>ripgrep</code>) with a lockfile</td><td>Same job</td></tr><tr><td><code>installer</code> (<code>.dmg</code>): download, SHA-256, signature refusal, copy one app, undo, unmount</td><td>Unit test (<code>internal/backend</code>) builds a real disk image and runs the real mount, copy and undo into a temporary folder; it runs wherever <code>go test</code> runs on macOS. Not tried with a real, signed vendor download, and the signature check of a genuinely signed and notarized app is covered only by parsing sample <code>spctl</code> output</td></tr><tr><td>Built-in recipes on macOS</td><td><code>git</code>, <code>node</code>, <code>typescript</code> (via npm), <code>chrome</code>, <code>firefox</code>, <code>vscode</code>, <code>docker</code>, <code>ripgrep</code>. The CI job checks every Homebrew package named in them exists</td></tr><tr><td>Users and groups (<code>ripeat policy</code>)</td><td><strong>Not supported</strong>: it stops with an error and changes nothing</td></tr><tr><td>Restart detection</td><td>Never reports a restart</td></tr><tr><td>Intel Macs</td><td>Built in releases, never run</td></tr><tr><td>Signing and notarization</td><td>None, by decision: ripeat is a hobby project (release notes for maintainers)</td></tr></tbody></table>',18)])])}const m=t(r,[["render",n]]);export{u as __pageData,m as default};
